"use client"

import { RouteError } from "@/components/route-error"

export default function RouteErrorPage({
  error,
  reset,
}: Readonly<{
  error: Error & { digest?: string }
  reset: () => void
}>) {
  return <RouteError error={error} reset={reset} />
}

import { RouteLoading } from "@/components/route-loading"

export default function Loading() {
  return <RouteLoading />
}

"use client"

import { FileMagnifyingGlassIcon } from "@phosphor-icons/react/dist/ssr"

import { AuditCodeTag } from "@/components/audit-code-tag"
import { RiskTable, type RiskTableColumn } from "@/components/patterns/risk-table/risk-table"
import { SectionPanelHeader } from "@/components/section-panel-header"
import { Card, CardContent } from "@/components/ui/card"
import type { EwsEvidenceRow } from "@/lib/templates/ews-data"

/**
 * 진단 근거 · 감사 추적 — `risk-table`(#87) 에 컬럼 정의만 주입하고, 코드 열은
 * `audit-code-tag`(#83) 가 그린다.
 *
 * #89 의 긴급 처리 차주 표와 같은 패턴을 쓰지만 열 구성이 전혀 다르다(식별·금액
 * 대신 코드·출처·관측 시각). 패턴에 분기를 더하지 않고 컬럼만 갈아끼워 다른
 * 성격의 표가 만들어지는지가 이 화면의 검증 지점이다.
 */
const COLUMNS: RiskTableColumn<EwsEvidenceRow>[] = [
  {
    key: "code",
    header: "감사코드",
    cell: (row) => <AuditCodeTag code={row.code} copyable />,
  },
  {
    key: "source",
    header: "자료 출처",
    cell: (row) => row.source,
  },
  {
    key: "observation",
    header: "관측 내용",
    kind: "wrap",
    cell: (row) => <span className="text-muted-foreground">{row.observation}</span>,
    className: "min-w-[14rem]",
  },
  {
    key: "collectedAt",
    header: "수집 시각",
    cell: (row) => <span className="font-mono text-xs tabular-nums">{row.collectedAt}</span>,
  },
]

export function EvidenceTrailCard({ rows }: Readonly<{ rows: EwsEvidenceRow[] }>) {
  return (
    <Card className="min-w-0">
      <SectionPanelHeader
        icon={FileMagnifyingGlassIcon}
        title="진단 근거 · 감사 추적"
        description="기여 변수를 뒷받침한 원자료와 수집 시각"
        meta={`${rows.length}건`}
      />
      <CardContent>
        <RiskTable
          columns={COLUMNS}
          rows={rows}
          getRowKey={(row) => row.id}
          getRowSeverity={(row) =>
            row.level === "low" ? undefined : { level: row.level, label: `${row.levelLabel} 등급 근거` }
          }
          caption="경보 원인 진단의 근거 자료 목록"
          captionHidden
          emptyLabel="수집된 근거 자료가 없습니다."
        />
      </CardContent>
    </Card>
  )
}

"use client"

import { RankingIcon } from "@phosphor-icons/react/dist/ssr"

import { ContributionMeter } from "@/components/contribution-meter"
import { SectionPanelHeader } from "@/components/section-panel-header"
import { Card, CardContent } from "@/components/ui/card"
import type { EwsDiagnosisFactor } from "@/lib/templates/ews-data"

/**
 * 경보 기여 변수 랭킹 — `contribution-meter`(#84) 를 목록으로 반복하는 자리다.
 *
 * 게이지·퍼센트·감사코드·방향 아이콘은 전부 파츠가 소유하고, 이 화면이 더하는
 * 것은 순위 번호와 변수명·관측값 두 줄뿐이다. 기여 방향을 색으로만 구분하지
 * 않도록 `direction` 을 그대로 넘겨 파츠가 아이콘과 sr-only 문구를 싣게 한다.
 */
export function FactorRankingCard({
  factors,
  scoreLabel,
  modelLabel,
}: Readonly<{ factors: EwsDiagnosisFactor[]; scoreLabel: string; modelLabel: string }>) {
  return (
    <Card className="min-w-0">
      <SectionPanelHeader
        icon={RankingIcon}
        title="경보 기여 변수"
        description={modelLabel}
        meta={scoreLabel}
      />
      <CardContent>
        <ol className="flex flex-col gap-4">
          {factors.map((factor, index) => (
            <li key={factor.key} className="flex min-w-0 flex-col gap-1.5">
              <div className="flex min-w-0 items-baseline gap-2">
                <span className="shrink-0 font-mono text-xs text-muted-foreground tabular-nums">
                  {index + 1}위
                </span>
                <span className="min-w-0 truncate text-sm font-medium">{factor.label}</span>
              </div>
              <ContributionMeter
                percent={factor.percent}
                direction={factor.direction}
                code={factor.code}
                copyable
              />
              <p className="text-xs text-muted-foreground">{factor.note}</p>
            </li>
          ))}
        </ol>
      </CardContent>
    </Card>
  )
}
